import ezdxf, sys
src = r'C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\25-11-2026\521125-21\SNK-NBK-CLM-FR-01 フレーム.dxf'
x0, y0, x1, y1 = [float(v) for v in sys.argv[1:5]]
d = ezdxf.readfile(src)
def inb(x, y): return x0 <= x <= x1 and y0 <= y <= y1
rows = []
for e in d.modelspace():
    t = e.dxftype(); L = e.dxf.layer
    if t == 'LINE':
        a, b = e.dxf.start, e.dxf.end
        if inb(a.x, a.y) and inb(b.x, b.y):
            rows.append((L, 'LINE', round(a.x, 2), round(a.y, 2), round(b.x, 2), round(b.y, 2)))
    elif t in ('ARC', 'CIRCLE'):
        c = e.dxf.center
        if inb(c.x, c.y):
            rows.append((L, t, round(c.x, 2), round(c.y, 2), round(e.dxf.radius, 2), round(getattr(e.dxf, 'start_angle', 0), 1), round(getattr(e.dxf, 'end_angle', 360), 1)))
    elif t == 'DIMENSION':
        try:
            rows.append((L, 'DIM', round(e.get_measurement(), 2) if hasattr(e, 'get_measurement') else '', e.dxf.text, tuple(round(v, 1) for v in e.dxf.defpoint)))
        except Exception as ex:
            rows.append((L, 'DIM', str(ex)))
sel = sys.argv[5].split(',') if len(sys.argv) > 5 else None
for r in sorted(rows, key=lambda r: (r[0], r[1], r[2:] if isinstance(r[2], float) else (0,))):
    if sel and r[0] not in sel: continue
    print(*r)

